  "archived_at"?: string;
  "status": CRMLeadStatus;
  "qualification_reason"?: string;
  "reject_reason_id"?: UUID;
  "converted_deal_id"?: UUID;
  /** Во что вошло это обращение при слиянии дублей; заполнено только у архивной записи-источника */
