  "marked": boolean;
  "mode": "" | "unit" | "gtin";
  "group": string;
  /** Сколько кодов ждёт строка */
  "required": number;
  "assigned": number;
  "strictness": MarkingStrictness;
  "status": "ok" | "missing" | "excess" | "not_required";
  "codes": Array<MarkingStockLineCode> | null;
