  "expected": number;
  /** Ожидаемые коды без криптохвоста */
  "expected_codes": Array<string> | null;
  "expected_packages": Array<MarkingExpectedPackage> | null;
  /** Отсканировано из ожидаемых */
  "accepted": number;
  /** Ожидались по УПД и не отсканированы */
